from collections import Counter

corpus = {"kitap": 5, "kitaplar": 3, "kitabi": 2, "kalem": 4, "kalemler": 2}
vocab = {tuple(w) + ("</w>",): c for w, c in corpus.items()}

for adim in range(1, 4):
    cift = Counter()
    for sym, c in vocab.items():
        for i in range(len(sym) - 1):
            cift[(sym[i], sym[i + 1])] += c
    en_iyi, sayi = max(cift.items(), key=lambda kv: (kv[1], kv[0]))
    print(adim, "".join(en_iyi), sayi)
    yeni = {}
    for sym, c in vocab.items():
        out, i = [], 0
        while i < len(sym):
            if i < len(sym) - 1 and (sym[i], sym[i + 1]) == en_iyi:
                out.append(sym[i] + sym[i + 1]); i += 2
            else:
                out.append(sym[i]); i += 1
        yeni[tuple(out)] = yeni.get(tuple(out), 0) + c
    vocab = yeni

print(" ".join(next(iter(vocab))))

