import math

def parca_sayisi(n, boyut, bindirme):
    adim = boyut - bindirme
    if n <= boyut:
        return 1
    return math.ceil((n - boyut) / adim) + 1

print("bindirmeli :", parca_sayisi(40000, 512, 64))
print("bindirmesiz:", math.ceil(40000 / 512))

def kosinus(u, v):
    nokta = sum(a * b for a, b in zip(u, v))
    return nokta / (math.sqrt(sum(a * a for a in u)) * math.sqrt(sum(b * b for b in v)))

